function renderConnectionHealth(){
 const h=S.status.health,a=h.alpaca,w=h.webull,k=h.kx||{},sx=h.spx||{},stream=S.status.stream,accounts=S.account?.accounts||[];
 const webullLabel=S.account?.status==='READ_ONLY_ACCOUNT_OBSERVED'?'SANDBOX READ OK':w.status==='READ_ONLY_SANDBOX_PROBE_OBSERVED'?'SANDBOX DATA OK':'UNVERIFIED';
 const spxLabel=({IMPORT_REQUIRED:'MISSING',SYNTHETIC_ONLY:'SYNTHETIC ONLY',LOCAL_CHAIN_SAVED_REVIEW_REQUIRED:'CHAIN SAVED'})[sx.status]||'UNKNOWN';
 const blockers=(k.blockers||[]).map(x=>`<li>${E(String(x).replaceAll('_',' '))}</li>`).join('');
 const candidates=(sx.localCandidates||[]).map(x=>`<div class="audit-item"><div><h3>${E(x.name)} · ${E(x.status)}</h3><p>${E((x.identities||[]).join(', ')||'Identity unavailable')} · ${num(x.rows,0)} rows</p><p>${E(x.recovery)}</p></div>${tag(x.eligibleForImportReview?'REVIEW':'DO NOT IMPORT',x.eligibleForImportReview?'amber':'red')}</div>`).join('');
 return panel('Data & connection health','Configuration is never presented as proof of entitlement',`<div class="panel-body"><div class="metrics">${metric('OFFLINE CORE',h.offlineCore.status,'Saved/imported research is available','small positive')}${metric('ALPACA IEX',E(stream.status),a.coverage,'small')}${metric('WEBULL HK',webullLabel,S.account?'Sandbox account read '+dt(S.account.checked_at):w.lastCheckedAt?'Last market-data check '+dt(w.lastCheckedAt):'No current read-only check','small')}${metric('SPX CHAIN',spxLabel,E(sx.recovery||'Review SPX chain status'),'small')}${metric('KX RELEASE',E(k.status||'UNKNOWN'),k.sourceHashMatch?'Source hash matches; '+num(k.blockerCount,0)+' gates remain':'Release evidence is missing or mismatched','small amber')}${metric('BROKER ORDERS','PAPER CONFIRM','Webull sandbox only · production unreachable','small amber')}${metric('DB SCHEMA','v'+S.status.migration.userVersion,'Idempotent migration receipt present','small')}</div>${accounts.length?`<div class="notice info wide-space"><strong>SANDBOX ACCOUNT STATE · PRIVATE LOCAL VIEW</strong>${accounts.map(a=>`<p>${E(a.account)} · ${E(a.account_type||'type unknown')} · ${(a.positions||[]).length} position rows · ${num(a.openOrderCount,0)} open order rows<br>${(a.balances||[]).map(b=>Object.entries(b).map(([key,value])=>E(key)+': '+E(value)).join(' · ')).join('<br>')||'No allowlisted balance values returned'}</p>`).join('')}<span class="form-help">Read-only sandbox data is held in memory and is not production permission or a trade recommendation.</span></div>`:''}<div class="grid-two wide-space"><div><h3>KX release authorization</h3><p>${E(k.recovery||'KX evidence is unavailable.')}</p><p class="form-help">Candidate ${E(k.candidateStatus||'UNKNOWN')} · manifest ${E(k.releaseState||'UNKNOWN')} / ${E(k.acceptanceState||'UNKNOWN')} · compiled ${k.compiled?'yes':'no'} · source hash ${k.sourceHashMatch?'matches':'unverified'}</p>${blockers?`<details><summary>${num(k.blockerCount,0)} blocking gates</summary><ul class="checklist">${blockers}</ul></details>`:'<p class="subtle">No KX blockers were reported.</p>'}</div><div><h3>SPX input readiness</h3><p>${E(sx.recovery||'Import a native SPX/SPXW chain.')}</p>${candidates||'<p class="subtle">No local chain candidate was found. Use the SPX GEX import form with an authorized native export.</p>'}</div></div><div class="grid-two wide-space"><div><h3>Research source paths</h3>${h.sources.map(x=>`<div class="audit-item"><div><h3>${E(x.name)} · ${E(x.status)}</h3><p>${E(x.recovery)}</p></div></div>`).join('')}</div><div><h3>Webull recovery actions</h3><p>${E(w.recovery)}</p><p>Production account: <strong>${E(w.productionAccount||'UNVERIFIED')}</strong> · API market-data entitlement: <strong>${E(w.marketDataEntitlement||'UNVERIFIED')}</strong>.</p><p>SPX sandbox option coverage: <strong>${E(w.spxOptionSandbox?.status||'UNVERIFIED')}</strong>${w.spxOptionSandbox?.checkedAt?' · checked '+E(dt(w.spxOptionSandbox.checkedAt)):''}. ${E(w.spxOptionSandbox?.note||'This is a field-coverage check only.')}</p><div class="row">${button('Check Webull market data','webull-probe','small')}${button('Check SPX sandbox coverage','webull-spx','small')}${button('Read sandbox account state','webull-account','small')}</div><p class="form-help">Account and market checks are read-only. Paper submission uses the official SDK only after preview plus exact confirmation. SPX field checks do not qualify current GEX.</p></div></div></div>`,tag('RESEARCH ONLY','neutral'));
}
