// Quant charts below are local. The optional TradingView display is sandboxed.
function canvasPlot(id,config){
 const c=document.getElementById(id);if(!c)return;const box=c.parentElement.getBoundingClientRect(),w=Math.max(220,box.width),h=Math.max(180,box.height||300),dpr=Math.min(devicePixelRatio||1,2);c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);c.style.width=w+'px';c.style.height=h+'px';const ctx=c.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);
 const col={grid:'#253344',text:'#7c90a7',up:'#64d8ac',down:'#f1889b',gold:'#dfbd74',blue:'#82aef0'};ctx.font='11px system-ui';const p={l:16,r:78,t:20,b:33},pw=w-p.l-p.r,ph=h-p.t-p.b;
 const noData=()=>{ctx.fillStyle=col.text;ctx.textAlign='center';ctx.fillText('Not enough completed observations for this chart',w/2,h/2);};
 if(config.type==='candles'){
  const all=config.bars||[],end=Math.max(1,all.length-S.pan),start=Math.max(0,end-S.zoom),bars=all.slice(start,end);if(!bars.length){noData();return;}const e20=GQ.ema(all.map(b=>b.c),20).slice(start,end),e50=GQ.ema(all.map(b=>b.c),50).slice(start,end);
  let low=Math.min(...bars.map(b=>b.l),...e20.filter(Number.isFinite),...e50.filter(Number.isFinite)),high=Math.max(...bars.map(b=>b.h),...e20.filter(Number.isFinite),...e50.filter(Number.isFinite));const pad=Math.max((high-low)*.09,.01);low-=pad;high+=pad;
  const y=v=>p.t+(high-v)/(high-low)*ph,x=i=>p.l+(i+.5)*pw/bars.length;
  for(let i=0;i<=5;i++){const value=low+(high-low)*i/5,yy=y(value);ctx.strokeStyle=col.grid;ctx.beginPath();ctx.moveTo(p.l,yy);ctx.lineTo(w-p.r,yy);ctx.stroke();ctx.fillStyle=col.text;ctx.textAlign='left';ctx.fillText(num(value),w-p.r+9,yy+4);}
  const vmax=Math.max(...bars.map(b=>b.v),1);bars.forEach((b,i)=>{ctx.fillStyle=b.c>=b.o?'#254d45':'#4a333f';ctx.fillRect(x(i)-pw/bars.length*.32,p.t+ph-b.v/vmax*ph*.15,Math.max(1,pw/bars.length*.64),b.v/vmax*ph*.15);ctx.strokeStyle=ctx.fillStyle=b.c>=b.o?col.up:col.down;ctx.beginPath();ctx.moveTo(x(i),y(b.h));ctx.lineTo(x(i),y(b.l));ctx.stroke();ctx.fillRect(x(i)-Math.max(1,pw/bars.length*.32),Math.min(y(b.o),y(b.c)),Math.max(1,pw/bars.length*.64),Math.max(1,Math.abs(y(b.o)-y(b.c))));});
  const line=(values,color)=>{ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.beginPath();let start=true;values.forEach((v,i)=>{if(!Number.isFinite(v)){start=true;return;}if(start){ctx.moveTo(x(i),y(v));start=false;}else ctx.lineTo(x(i),y(v));});ctx.stroke();ctx.lineWidth=1;};line(e20,col.gold);line(e50,col.blue);
  const count=w<500?3:5;for(let k=0;k<count;k++){const i=Math.round(k*(bars.length-1)/(count-1));ctx.fillStyle=col.text;ctx.textAlign=i===0?'left':i===bars.length-1?'right':'center';const t=new Date(bars[i].t),lab=new Intl.DateTimeFormat('en-GB',{timeZone:'America/New_York',...(config.minutes>=1440?{day:'2-digit',month:'short'}:new Set(bars.map(b=>GQ.eastern(b.t).date)).size>1?{day:'2-digit',month:'short'}:{hour:'2-digit',minute:'2-digit',hourCycle:'h23'})}).format(t);ctx.fillText(lab,x(i),h-10);}
  if(Number.isInteger(config.hoverIndex)&&config.hoverIndex>=0&&config.hoverIndex<bars.length){const i=config.hoverIndex,b=bars[i];ctx.strokeStyle='#a8bbcf';ctx.setLineDash([3,3]);ctx.beginPath();ctx.moveTo(x(i),p.t);ctx.lineTo(x(i),p.t+ph);ctx.moveTo(p.l,y(b.c));ctx.lineTo(w-p.r,y(b.c));ctx.stroke();ctx.setLineDash([]);}
  c.tabIndex=0;c.setAttribute('aria-label','OHLCV chart. Move pointer or use left and right arrow keys for the crosshair; use chart controls to zoom, pan or reset.');
  const show=i=>{config.hoverIndex=Math.max(0,Math.min(bars.length-1,i));const b=bars[config.hoverIndex],readout=$('#price-readout');if(readout)readout.textContent=`${dt(b.t)}   O ${num(b.o)}   H ${num(b.h)}   L ${num(b.l)}   C ${num(b.c)}   Vol ${num(b.v,0)}`;requestAnimationFrame(()=>canvasPlot(id,config));};
  c.onmousemove=event=>{const rect=c.getBoundingClientRect();show(Math.floor((event.clientX-rect.left-p.l)/pw*bars.length));};c.onkeydown=event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();show((Number.isInteger(config.hoverIndex)?config.hoverIndex:bars.length-1)+(event.key==='ArrowLeft'?-1:1));};return;
 }
 const points=(config.points||[]).filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y));if(!points.length){noData();return;}let xmin=Math.min(...points.map(v=>v.x)),xmax=Math.max(...points.map(v=>v.x)),ymin=Math.min(0,...points.map(v=>v.y)),ymax=Math.max(0,...points.map(v=>v.y));if(xmin===xmax){xmin-=1;xmax+=1;}const padding=Math.max((ymax-ymin)*.1,1);ymin-=padding;ymax+=padding;const x=v=>p.l+(v-xmin)/(xmax-xmin)*pw,y=v=>p.t+(ymax-v)/(ymax-ymin)*ph;
 for(let i=0;i<=4;i++){const value=ymin+(ymax-ymin)*i/4,yy=y(value);ctx.strokeStyle=col.grid;ctx.beginPath();ctx.moveTo(p.l,yy);ctx.lineTo(w-p.r,yy);ctx.stroke();ctx.fillStyle=col.text;ctx.textAlign='left';ctx.fillText(config.money?compact(value):num(value,0),w-p.r+7,yy+4);}
 ctx.strokeStyle='#536277';ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(p.l,y(0));ctx.lineTo(w-p.r,y(0));ctx.stroke();ctx.setLineDash([]);
 if(config.type==='bars'){const bw=Math.max(2,pw/points.length*.68);points.forEach(pt=>{ctx.fillStyle=pt.y>=0?col.up:col.down;ctx.fillRect(Math.min(w-p.r-bw,x(pt.x)-bw/2),Math.min(y(0),y(pt.y)),bw,Math.max(1,Math.abs(y(pt.y)-y(0))));});}
 else{ctx.strokeStyle=col.up;ctx.lineWidth=2;ctx.beginPath();points.forEach((pt,i)=>i?ctx.lineTo(x(pt.x),y(pt.y)):ctx.moveTo(x(pt.x),y(pt.y)));ctx.stroke();}
 for(let i=0;i<5;i++){const value=xmin+(xmax-xmin)*i/4;ctx.fillStyle=col.text;ctx.textAlign=i===0?'left':i===4?'right':'center';ctx.fillText(num(value,value>=100?0:2),x(value),h-10);}
}
function drawCharts(){for(const [id,spec] of charts)canvasPlot(id,spec);}
function modal(title,body){$('#detail-title').textContent=title;$('#detail-content').innerHTML=body;$('#detail-dialog').showModal();requestAnimationFrame(drawCharts);}
function help(){modal('Start with your own research',`<div class="notice info"><strong>Local and free-first.</strong> No market subscription, API key or broker connection is required to use the saved data, library, imports and calculators.</div><h3>1. Choose a dataset</h3><p>Charts & symbols accepts user-selected tickers. Fetch local observations or enable the separate online display. Your archived SPY observations remain under Overview, with their original date.</p><h3>2. Explore the tools</h3><p>SPX GEX accepts native SPX/SPXW imports separately from your chart. A synthetic SPX walkthrough is available only when explicitly selected. Open Trade lab for defined-risk options payoff and futures stop/margin sizing. Search your existing documents under Research library.</p><h3>3. Add your observations</h3><p>Data desk accepts OHLCV CSV and full snapshot JSON. Free data is fetched on request, or by the Charts auto-refresh control while the tab is visible. It may be delayed, rate-limited or unavailable. Optional IEX needs free-account keys, covers one exchange and streams only after you press Start stream. No failed request silently changes the screen to demo data.</p><h3>4. Keep research distinct from trading</h3><p>GEX signs are model assumptions. Scenario scores are not backtested win probabilities. A journal note is not a fill. Webull sandbox paper submission requires a provider preview and a fresh typed confirmation for each order. Production execution remains disabled. Today & monitor compares conditional intraday/swing plans without submitting orders.</p><p><a href="/api/guide">Read the full setup and limitations guide ↓</a></p>`);}
function render(){if(!S.status)return;const detailsKey=e=>(e.closest('[data-instrument]')?.dataset.instrument||'')+'|'+e.querySelector('summary')?.textContent,opened=new Set([...document.querySelectorAll('#content details[open]')].map(detailsKey));charts.clear();$('#current-page').textContent=nav.find(n=>n[0]===S.page)?.[2]||'Overview';document.title=`${$('#current-page').textContent} · Trading Research Hub`;$('#navigation').innerHTML=nav.filter(n=>['home','research','data'].includes(n[0])).map(([key,icon,label])=>`<a href="#${key}" class="nav-link ${S.page===key?'active':''}" ${S.page===key?'aria-current="page"':''}><span>${icon}</span>${key==='research'?'Research':key==='data'?'Settings':label}</a>`).join('');$('#workbench-links').innerHTML=nav.filter(n=>!['home','research','data'].includes(n[0])).map(([key,icon,label])=>`<a href="#${key}" ${S.page===key?'aria-current="page"':''}>${E(label)}</a>`).join('');const renders={home:renderHome,monitor:renderMonitor,options:renderTrade,charts:renderCharts,overview:renderOverview,gex:renderGex,trade:renderTrade,stocks:renderStocks,backtests:renderBacktests,research:renderResearch,journal:renderJournal,data:renderData};try{$('#content').innerHTML=renders[S.page]();}catch(e){console.error(e);message('This view could not render: '+e.message);$('#content').innerHTML=empty('View error','Your stored files have not been replaced. Reload the page or use Data desk.');}document.querySelectorAll('#content details').forEach(e=>{if(opened.has(detailsKey(e)))e.open=true;});requestAnimationFrame(drawCharts);if(S.page==='charts')updateChartStatus();updateAlertBanner();}
async function preparePage(page){if(page==='home')await prepareHome();if(page==='options')S.lab='options';if(page==='monitor')await prepareMonitor();if(page==='charts')await prepareCharts();if(page==='gex')await prepareSPX();if(page==='research')S.research=await api('/api/research?q='+encodeURIComponent(S.search)+'&stream='+encodeURIComponent(S.stream)+'&internal='+(S.showInternal?'1':'0'));if(page==='journal')[S.notes,S.records]=await Promise.all([api('/api/notes'),api('/api/records?kind='+S.recordKind)]);if(page==='backtests'){S.runs=await api('/api/backtests');if(!S.runs.some(r=>r.id===S.runId))S.runId=S.runs[0]?.id;}if(page==='stocks')await prepareScanner();}
async function go(){const page=location.hash.slice(1);S.page=nav.some(n=>n[0]===page)?page:'home';if(!monitorViewActive()&&!monitorBackgroundAllowed())stopMonitor('Paused: monitor view is not active.');$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');message('');try{if(S.page!=='charts'&&C.stream&&C.stream.status!=='OFF'){C.stream=await api('/api/stream/stop',{});stopStreamRelay();}await preparePage(S.page);render();if(S.page==='charts')scheduleChartRefresh();else stopChartTimer();}catch(e){message(e.message);render();}}
async function importResult(result){await refreshStatus();S.cache.delete(result.id);await loadSnapshot(result.id);notify('Validated snapshot saved locally. Source labels remain attached.');render();}
async function fetchSymbol(symbol,interval,options){notify('Requesting public research data. Your saved dataset stays intact.');try{const r=await api('/api/fetch',{symbol,interval,options});await refreshStatus();S.cache.delete(r.id);return r;}catch(e){await refreshStatus();throw e;}}
async function act(action,el){
 if(action.startsWith('alert-'))return alertAction(action,el);
 if(action==='options-fetch')return fetchOptionsForSymbol();
 if(action.startsWith('home-'))return homeAction(action,el);
 if(action.startsWith('monitor-'))return monitorAction(action,el);
 if(action.startsWith('chart-'))return chartAction(action,el);
 if(action==='load-spx-demo'||action==='spx-export'||action==='spx-preview-download')return spxAction(action);
 if(action==='timeframe'){S.frame=Number(el.dataset.frame);render();}
 else if(action==='zoom-out'||action==='zoom-in'){S.zoom=Math.max(30,Math.min(240,S.zoom+(action==='zoom-out'?30:-30)));S.pan=0;render();}
 else if(action==='open-fetch'){location.hash='data';setTimeout(()=>$('#fetch-symbol')?.focus(),50);}
 else if(action==='export-snapshot'){const blob=new Blob([JSON.stringify(S.s,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=S.s.symbol+'-research-snapshot.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 else if(action==='load-demo'){const d=S.snapshots.find(d=>d.dataKind==='synthetic');if(!d)throw Error('Synthetic example is missing. Import examples/web/demo-gex.json.');await loadSnapshot(d.id);render();notify('Synthetic dataset selected explicitly. All figures are fictional.');}
 else if(action==='lab-options'||action==='lab-futures'){S.lab=action==='lab-options'?'options':'futures';render();}
 else if(action==='toggle-freeze'){S.prefs=await api('/api/settings',{...S.prefs,eventFreeze:!S.prefs.eventFreeze});processMonitorAlerts();render();}
 else if(action==='inspect-idea'){const p=S.ideas[Number(el.dataset.index)];modal(p.label,payoffResult(p,'idea-payoff')+`<div class="notice">${p.warnings.map(E).join('<br>')}</div><p>Snapshot cutoff: ${E(dt(S.s.asOf))}. Size is a paper calculation only.</p>`);}
 else if(action==='save-idea'){const snapshot=S.s,snapshotId=S.id,p=S.ideas[Number(el.dataset.index)],raw=new TextEncoder().encode(JSON.stringify({instrument:snapshot.instrumentId,options:snapshot.options,asOf:snapshot.asOf,source:snapshot.source})),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',raw))].map(x=>x.toString(16).padStart(2,'0')).join('');await api('/api/notes',{symbol:snapshot.symbol,category:'research',snapshotId,dataKind:snapshot.dataKind,text:JSON.stringify({schema:'hub.option-review.v1',ruleVersion:'stock-option-review-1',instrument:snapshot.instrumentId,source:snapshot.source,sourceHash:hash,barDataHash:await monitorHash(snapshot),snapshotAsOf:snapshot.asOf,knownAt:new Date().toISOString(),...p,maxGainUnbounded:p.maxGain===Infinity,quantityApproved:false,orderSubmitted:false})});notify('Conditional option review and exact contract details saved. No trade placed.');}
 else if(action==='fetch-stock'){await fetchSymbol(el.dataset.symbol,'1d',false);await prepareScanner();render();notify('Public research snapshot saved. Check its observation date.');}
 else if(action==='inspect-stock'){await loadSnapshot(el.dataset.id);location.hash='overview';if(S.page==='overview')render();}
 else if(action==='open-document'){const d=await api('/api/document?id='+encodeURIComponent(el.dataset.id));modal(d.title||'Saved document',`<div class="doc-meta">${E(d.source)} · ${E(d.stream)} · ${E(d.coverage||'Coverage not specified')}</div><p>${d.url?`<a href="${E(safeURL(d.url))}" target="_blank" rel="noopener noreferrer">Open original source ↗</a>`:''}</p><div class="doc-text">${E(d.text||d.body||JSON.stringify(d,null,2))}</div>`);}
 else if(action==='run-backtest'){notify('Running the original Hub backtest on your saved sandbox capture.');const r=await api('/api/backtests/run',{});await preparePage('backtests');await refreshStatus();render();notify('Backtest run saved. This is a sandbox regression, not a qualified live strategy.');}
 else if(action==='open-record'){const r=S.records.find(r=>r.id===el.dataset.id);modal('Preserved Hub record',`<pre class="json-view">${E(JSON.stringify(r.record,null,2))}</pre>`);}
 else if(action==='paper-status'){if(!S.paperResult?.order)throw Error('No paper order is available to reconcile.');S.paperResult=await api('/api/broker/paper/status',{order:S.paperResult.order});render();notify('Sandbox order status refreshed.');}
 else if(action==='paper-download'){if(!S.paperResult)throw Error('No paper receipt is available.');downloadJSON(S.paperResult,'Webull-sandbox-paper-receipt.json');}
 else if(action==='refresh-fed'){notify('Refreshing the preserved macro corpus and bounded public news summaries.');const r=await api('/api/research/refresh',{});await refreshStatus();await preparePage('research');render();notify((r.result.status==='COMPLETE'&&r.structure?.status==='COMPLETE'?'Bounded refresh complete. ':'Refresh partial; a source needs attention. ')+(r.result.counts.new_documents+r.structure.counts.new_documents)+' new documents. X browser review and full Brooks review remain separate; calendar gaps remain unknown.');}
 else if(action==='webull-probe'){notify('Running a bounded read-only Webull HK sandbox check.');await api('/api/webull/probe',{});await refreshStatus();render();notify('Read-only Webull sandbox check completed. Review the timestamp and entitlement limits.');}
 else if(action==='webull-spx'){notify('Checking Webull HK sandbox for native SPX option fields. No values will be imported and no order request is available.');const r=await api('/api/webull/spx',{});await refreshStatus();render();notify(r.status==='SANDBOX_SPX_OPTIONS_OBSERVED'?'Native SPX option fields were observed in sandbox. They remain unqualified for current-market GEX.':'Sandbox SPX option coverage was not established; review the provider status.');}
 else if(action==='webull-account'){notify('Reading sanitized Webull HK sandbox account state through GET-only SDK methods.');S.account=await api('/api/webull/account',{});render();notify(S.account.status==='READ_ONLY_ACCOUNT_OBSERVED'?'Sandbox account state observed. Production and order permissions remain unverified.':'No sandbox account was visible; review the nonsecret capability status.');}
}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const disabledBefore=el.disabled;el.disabled=true;try{await act(el.dataset.action,el);}catch(e){notify(e.message,true);message(e.message);}finally{if(el.isConnected)el.disabled=disabledBefore;}});
document.addEventListener('change',async event=>{const el=event.target;try{
 if(el.id==='option-symbol'){S.optionSymbol=el.value.trim();return;}
 if(el.id==='option-budget'){const value=el.value.trim();S.optionBudget=value===''?null:Number(value);if(S.optionBudget!==null&&(!Number.isFinite(S.optionBudget)||S.optionBudget<0)){S.optionBudget=null;throw Error('Premium budget must be nonnegative or blank.');}if(S.manual)S.manual.contracts=S.optionBudget==null?null:Math.floor(S.optionBudget/S.manual.maxLoss);return render();}
 if(el.id==='chart-interval'||el.id==='chart-provider'){
  C.generation++;stopChartTimer();C[el.id==='chart-interval'?'interval':'provider']=el.value;C.snapshot=null;C.error='';C.lastSuccess=null;C.failures=0;if(C.provider==='yahoo'&&C.auto===15)C.auto=60;saveChartPrefs();render();scheduleChartRefresh();
 }
 else if(el.id==='chart-refresh'){C.auto=Number(el.value);C.failures=0;scheduleChartRefresh();updateChartStatus();}
 else if(el.id==='chart-timezone'){C.timezone=el.value;saveChartPrefs();render();}
 else if(el.id==='chart-saved'&&el.value){C.generation++;const generation=C.generation;C.auto=0;stopChartTimer();const d=await api('/api/snapshot?id='+encodeURIComponent(el.value));if(generation!==C.generation)return;if(d.symbol!==C.symbol)throw Error('Saved symbol mismatch');C.snapshot=d;C.interval=({1:'1m',5:'5m',15:'15m',60:'1h',240:'4h',1440:'1d',10080:'1w'})[d.barMinutes]||'15m';C.lastSuccess=null;C.error='';render();}
 else if(el.id==='spx-dataset'){if(el.value)await loadSPX(el.value);else{S.gexSnapshot=null;S.gexId=null;localStorage.removeItem('hub.spx.snapshot');}render();}
 else if(el.id==='spx-file'&&el.files[0]&&/template|demo|synthetic/i.test(el.files[0].name)){$('#spx-import-form [name=synthetic]').checked=true;}
 else if(el.id==='active-dataset'){await loadSnapshot(el.value);render();}
 else if(el.id==='gex-convention'){S.gexScenario=null;S.gexConvention=el.value;render();}
 else if(el.id==='gex-days'){S.gexScenario=null;S.gexDays=Number(el.value);render();}
 else if(el.id==='model-rate'||el.id==='model-dividend'){const v=Number(el.value);if(!Number.isFinite(v)||v<(el.id==='model-rate'?-.1:0)||v>1)throw Error('Enter a decimal rate between -0.1 and 1 (dividend yield 0–1).');S.gexScenario=null;S.gexSnapshot={...S.gexSnapshot,[el.id==='model-rate'?'rate':'dividend']:v,warnings:[...new Set([...S.gexSnapshot.warnings,'Rate/dividend assumptions edited in the browser; underlying market observations are unchanged.'])]};render();}
 else if(el.id==='option-direction'){S.direction=el.value;render();}
 else if(el.id==='option-style'){S.style=el.value;render();}
 else if(el.id==='scanner-frame'){S.scannerFrame=el.value;await prepareScanner();render();}
 else if(el.id==='backtest-select'){S.runId=el.value;render();}
 else if(el.id==='record-kind'){S.recordKind=el.value;S.records=await api('/api/records?kind='+S.recordKind);render();}
 else if(el.id==='data-file'&&el.files[0]&&/template|demo|synthetic/i.test(el.files[0].name)){$('#data-import-form [name=synthetic]').checked=true;}
 else if(el.name==='symbol'&&el.closest('#futures-form')){$('#futures-form [name=entry]').value='';$('#futures-form [name=stop]').value='';$('#futures-form [name=margin]').value='';S.future=null;S.futureInputs={...Object.fromEntries(new FormData(el.closest('#futures-form'))),symbol:el.value,entry:'',stop:'',margin:''};render();notify('Contract family changed. Enter new native entry/stop/margin values; no proxy conversion is made.');}
 }catch(e){notify(e.message,true);}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.id)return;event.preventDefault();const submit=form.querySelector('[type=submit]');if(submit?.disabled)return;const f=new FormData(form);if(submit)submit.disabled=true;try{
 if(form.id==='home-settings-form'){await applyHomeSettings(f);}
 else if(form.id==='expected-range-form'){applyExpectedRange(f);}
 else if(form.id==='monitor-settings-form'){await saveMonitorSettings(f);}
 else if(form.id==='chart-symbol-form'){await selectChartSymbol(f.get('symbol'));}
 else if(form.id==='gex-reprice-form'){await repriceGex(f);}
 else if(form.id==='spx-import-form'){await importSPX(form);}
 else if(form.id==='manual-option-form'){S.manualInputs=Object.fromEntries(f);const v={type:f.get('type'),buyStrike:Number(f.get('buyStrike')),sellStrike:f.get('sellStrike')===''?null:Number(f.get('sellStrike')),debit:Number(f.get('debit')),fees:Number(f.get('fees')),equity:S.prefs.equity,riskPct:S.prefs.riskPct};S.manual=HR.manualOption(v);S.manual.contracts=S.optionBudget==null?null:Math.floor(S.optionBudget/S.manual.maxLoss);render();}
 else if(form.id==='futures-form'){S.futureInputs=Object.fromEntries(f);const v={...S.futureInputs,equity:S.prefs.equity,riskPct:S.prefs.riskPct};for(const k of ['entry','stop','fee','slippageTicks'])v[k]=Number(v[k]);v.margin=f.get('margin')===''?null:Number(f.get('margin'));S.future=HR.futureRisk(v);render();}
 else if(form.id==='fetch-form'){const r=await fetchSymbol(f.get('symbol'),f.get('interval'),f.has('options'));await loadSnapshot(r.id);render();notify('Public snapshot loaded. Check source timestamps; this is not a certified real-time feed.');}
 else if(form.id==='data-import-form'){const file=f.get('file');if(!file?.size)throw Error('Choose a non-empty CSV or JSON file.');if(file.size>15000000)throw Error('File is larger than 15 MB. Export a smaller range.');const text=await file.text();let body;if(file.name.toLowerCase().endsWith('.csv'))body={format:'csv',text,originalName:file.name,metadata:{symbol:f.get('symbol'),barMinutes:Number(f.get('barMinutes')),timezone:f.get('timezone'),source:f.get('source')||file.name,dataKind:f.has('synthetic')?'synthetic':'imported'}};else{const snapshot=JSON.parse(text);if(f.has('synthetic'))snapshot.dataKind='synthetic';body={snapshot,rawText:text,originalName:file.name};}await importResult(await api('/api/import',body));}
 else if(form.id==='option-source-form'){S.optionSymbol=String(f.get('symbol')).trim();const budget=String(f.get('budget')).trim();S.optionBudget=budget===''?null:Number(budget);if(S.optionBudget!==null&&(!Number.isFinite(S.optionBudget)||S.optionBudget<0))throw Error('Enter a nonnegative premium budget or leave blank.');await fetchOptionsForSymbol();}
 else if(form.id==='option-import-form'){if(!S.id)throw Error('Load an underlying snapshot before attaching options.');const file=f.get('file');if(!file?.size||file.size>15000000)throw Error('Choose a non-empty option file under 15 MB.');const text=await file.text(),body={snapshotId:S.id,oiAsOf:f.get('oiAsOf')};if(file.name.toLowerCase().endsWith('.csv'))Object.assign(body,{format:'csv',text});else{const parsed=JSON.parse(text);body.options=Array.isArray(parsed)?parsed:parsed.options;}await importResult(await api('/api/import-options',body));}
 else if(form.id==='settings-form'){S.prefs=await api('/api/settings',{equity:Number(f.get('equity')),riskPct:Number(f.get('riskPct')),watchlist:f.get('watchlist').split(',').map(s=>s.trim().toUpperCase()).filter(Boolean),favorites:f.get('favorites').split(',').map(s=>s.trim().toUpperCase()).filter(Boolean),eventFreeze:f.has('eventFreeze')});await refreshStatus();render();notify('Paper risk, watchlist and favorites saved locally.');}
 else if(form.id==='research-search-form'){S.search=f.get('query');S.stream=f.get('stream');S.showInternal=f.has('internal');await preparePage('research');render();}
 else if(form.id==='note-form'){await api('/api/notes',{symbol:f.get('symbol'),category:f.get('category'),text:f.get('text'),snapshotId:S.id,dataKind:S.s?.dataKind});await preparePage('journal');render();notify('Research note saved to SQLite. No broker fill claimed.');}
 else if(form.id==='record-import-form'){const file=f.get('file');if(!file?.size||file.size>1000000)throw Error('Choose a Hub JSON record under 1 MB.');await api('/api/record-import',{kind:f.get('kind'),record:JSON.parse(await file.text())});await preparePage('journal');render();notify('Record passed the original Hub validator and was stored.');}
 else if(form.id==='broker-paper-preview-form'){S.paperResult=null;S.paper=await api('/api/broker/paper/preview',{symbol:f.get('symbol'),side:f.get('side'),quantity:Number(f.get('quantity')),limitPrice:f.get('limitPrice'),accountSuffix:f.get('accountSuffix'),orderType:'LIMIT',timeInForce:'DAY'});render();notify('Webull sandbox preview accepted. No order was sent; type the exact phrase to submit.');}
 else if(form.id==='broker-paper-confirm-form'){if(!S.paper)throw Error('Paper preview expired or is missing.');S.paperResult=await api('/api/broker/paper/confirm',{challengeId:S.paper.challengeId,confirmation:f.get('confirmation')});S.paper=null;render();notify('Paper order submission returned '+S.paperResult.state+'.');}
 else if(form.id==='broker-paper-cancel-form'){if(!S.paperResult?.order)throw Error('No paper order is available to cancel.');S.paperResult=await api('/api/broker/paper/cancel',{order:S.paperResult.order,confirmation:f.get('confirmation')});render();notify('Paper cancellation request returned '+S.paperResult.state+'.');}
 }catch(e){const box=form.id==='manual-option-form'?$('#manual-error'):form.id==='futures-form'?$('#futures-error'):null;if(box){box.textContent=e.message;box.className='notice error wide-space';}notify(e.message,true);if(!box)message(e.message);}finally{if(submit?.isConnected)submit.disabled=false;}});
$('#dialog-close').addEventListener('click',()=>$('#detail-dialog').close());$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog'))$('#detail-dialog').close();});$('#help-button').addEventListener('click',help);$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});window.addEventListener('resize',()=>{clearTimeout(window.chartResize);window.chartResize=setTimeout(drawCharts,100);});window.addEventListener('hashchange',go);
async function start(){try{await refreshStatus();const saved=localStorage.getItem('hub.snapshot'),initial=S.snapshots.find(s=>s.id===saved)||S.snapshots.find(s=>s.symbol==='SPY'&&s.dataKind==='sandbox')||S.snapshots.find(s=>s.dataKind!=='synthetic')||S.snapshots[0];if(initial)await loadSnapshot(initial.id);$('#local-clock').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date())+' LONDON';await go();}catch(e){$('#content').innerHTML=empty('Could not open the local workspace',e.message+' Start the included launcher and open its localhost URL, rather than opening index.html directly.');message(e.message);}}
